### How to Use SideMenuExpansionItem
```
SideMenuExpansionItem SideMenuExpansionItem({
  Key? key,
  String? title,
  Icon? icon,
  Widget? iconWidget,
  required List<SideMenuItem> children,
})


```

#### Example

```
SideMenu(
    // Other Parameters
   items:[
      // Other items
      SideMenuItem(
         title: 'Normal Item 1',
         onTap: (page, _) {
            sideMenu.changePage(page);
         },
         icon: const Icon(Icons.supervisor_account),
      ),
      SideMenuExpansionItem(
         title: "Expansion Item",
         icon: Icon(Icons.kitchen),
         children: [
           SideMenuItem(
              title: 'Expansion Item 1',
              onTap: (page, _) {
                   sideMenu.changePage(page);
               },
               icon: const Icon(Icons.home),
               badgeContent: const Text(
                  '3',
                  style: TextStyle(color: Colors.white),
               ),
              tooltipContent:"Expansion Item 1",
           ),
           SideMenuItem(
              title: 'Expansion Item 2',
              onTap: (page, _) {
                   sideMenu.changePage(page);
               },
               icon: const Icon(Icons.supervisor_account),
           )
         ]
      ),
      SideMenuItem(
         title: 'Normal Item 2',
         onTap: (page, _) {
            sideMenu.changePage(page);
         },
         icon: const Icon(Icons.supervisor_account),
      ),
                 
   ]
)

/*
The Page Number for `Expansion Item 1` is one more than page number of `Normal Item 1`. 
The Page Number for `Expansion Item 2` is one more than page number of `Expansion Item 1`. 
The Page Number for `Normal Item 2` is one more than page number of `Expansion Item 2`. 

*/


```

Add MQTT websocket to a custom HTTP server

```go
func main() {
        router := gin.Default()
	ginServer := &http.Server{
		Addr:    ":13000",
		Handler: router,
                 ReadTimeout:    10 * time.Second,
		WriteTimeout:   10 * time.Second,
		MaxHeaderBytes: 1 << 20,
	}
        server := mqtt.New(nil)
	_ = server.AddHook(new(auth.AllowHook), nil)
	ws := listeners.WebsocketFromHTTPServer("websocket", ginServer)
	if err := server.AddListener(ws); err != nil {
		log.Error(err.Error())
	}
	go func() {
		err := server.Serve()
		if err != nil {
			log.Error(err.Error())
		}
	}()
	router.GET("/socket", func(c *gin.Context) {
		ws.Handler(c.Writer, c.Request)
	})
	ginServer.ListenAndServe()
}
```

